CREATE OR REPLACE VIEW ARCHIVAL_STRATEGY_COMPARISON AS SELECT READING_ID, DATA_SIZE, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ACCESS_FREQUENCY, RECORD_STORAGE_UTILISATION, H_SCORE, CASE WHEN DAYS_SINCE_ACCESS >= 230 THEN 'ARCHIVE' ELSE 'KEEP' END AS TIME_BASED_DECISION, CASE WHEN H_SCORE >= 2.5 THEN 'ARCHIVE' ELSE 'KEEP' END AS HYBRID_DECISION FROM HYBRID_ARCHIVAL_NEW;

SELECT * FROM ARCHIVAL_STRATEGY_COMPARISON FETCH FIRST 10 ROWS ONLY;

SELECT READING_ID, DATA_SIZE, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ROUND(ACCESS_FREQUENCY, 4) AS ACCESS_FREQUENCY, ROUND(RECORD_STORAGE_UTILISATION, 6) AS U_I, ROUND(H_SCORE, 4) AS H_SCORE, TIME_BASED_DECISION, HYBRID_DECISION FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION <> HYBRID_DECISION
ORDER BY H_SCORE DESC
FETCH FIRST 20 ROWS ONLY;

SELECT TIME_BASED_DECISION || '_TO_' || HYBRID_DECISION AS DECISION_CHANGE, COUNT(*) AS RECORD_COUNT FROM ARCHIVAL_STRATEGY_COMPARISON
GROUP BY TIME_BASED_DECISION, HYBRID_DECISION
ORDER BY DECISION_CHANGE;

SELECT READING_ID, DAYS_SINCE_ACCESS, ACCESS_FREQUENCY, ROUND(RECORD_STORAGE_UTILISATION, 6) AS U_I, ROUND(H_SCORE, 4) AS H_SCORE, HYBRID_DECISION FROM ARCHIVAL_STRATEGY_COMPARISON
ORDER BY H_SCORE DESC
FETCH FIRST 10 ROWS ONLY;

SELECT 'TIME-BASED' AS STRATEGY, COUNT(*) AS TOTAL_ARCHIVED, SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) AS COLD_ARCHIVED, SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS ACTIVE_ARCHIVED, ROUND(100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418, 2) AS COLD_CAPTURE_RATE FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION = 'ARCHIVE'
UNION ALL
SELECT 'HYBRID', COUNT(*), SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END), SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END), ROUND(100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418, 2) FROM ARCHIVAL_STRATEGY_COMPARISON WHERE HYBRID_DECISION = 'ARCHIVE';

SELECT ROUND(100 * ( MAX(CASE WHEN STRATEGY = 'HYBRID' THEN COLD_CAPTURE_RATE END) - MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN COLD_CAPTURE_RATE END)) / MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN COLD_CAPTURE_RATE END), 4) AS RELATIVE_IMPROVEMENT_PERCENT, ROUND(MAX(CASE WHEN STRATEGY = 'HYBRID' THEN COLD_CAPTURE_RATE END) - MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN COLD_CAPTURE_RATE END), 4) AS PERCENTAGE_POINT_IMPROVEMENT FROM (SELECT 'TIME-BASED' AS STRATEGY, 100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418 AS COLD_CAPTURE_RATE FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION = 'ARCHIVE'
UNION ALL
SELECT 'HYBRID', 100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418 FROM ARCHIVAL_STRATEGY_COMPARISON WHERE HYBRID_DECISION = 'ARCHIVE');

SELECT ROUND(100 * (MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN ACTIVE_ARCHIVED END) - MAX(CASE WHEN STRATEGY = 'HYBRID' THEN ACTIVE_ARCHIVED END)) / MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN ACTIVE_ARCHIVED END), 4) AS ACTIVE_ARCHIVAL_REDUCTION_PERCENT FROM (
SELECT 'TIME-BASED' AS STRATEGY, SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS ACTIVE_ARCHIVED FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION = 'ARCHIVE'
UNION ALL
SELECT 'HYBRID', SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) FROM ARCHIVAL_STRATEGY_COMPARISON WHERE HYBRID_DECISION = 'ARCHIVE');

SELECT READING_ID, DATA_SIZE, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ACCESS_FREQUENCY, RECORD_STORAGE_UTILISATION, H_SCORE, HYBRID_DECISION FROM HYBRID_ARCHIVAL_NEW
FETCH FIRST 10 ROWS ONLY;

CREATE OR REPLACE VIEW ARCHIVAL_STRATEGY_COMPARISON AS SELECT READING_ID, DATA_SIZE, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ACCESS_FREQUENCY, RECORD_STORAGE_UTILISATION, H_SCORE, CASE WHEN DAYS_SINCE_ACCESS >= 230 THEN 'ARCHIVE' ELSE 'KEEP' END AS TIME_BASED_DECISION, CASE WHEN H_SCORE >= 2.5 THEN 'ARCHIVE' ELSE 'KEEP' END AS HYBRID_DECISION FROM HYBRID_ARCHIVAL_NEW;
SELECT * FROM ARCHIVAL_STRATEGY_COMPARISON FETCH FIRST 10 ROWS ONLY;

SELECT 'TIME-BASED' AS STRATEGY, COUNT(*) AS TOTAL_ARCHIVED, SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) AS COLD_ARCHIVED, SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS ACTIVE_ARCHIVED, ROUND(100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418, 2) AS COLD_CAPTURE_RATE FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION = 'ARCHIVE'
UNION ALL
SELECT 'HYBRID', COUNT(*), SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END), SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END), ROUND(100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418, 2) FROM ARCHIVAL_STRATEGY_COMPARISON WHERE HYBRID_DECISION = 'ARCHIVE';

SELECT READING_ID, DATA_SIZE, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ROUND(ACCESS_FREQUENCY, 4) AS ACCESS_FREQUENCY, ROUND(RECORD_STORAGE_UTILISATION, 6) AS U_I, ROUND(H_SCORE, 4) AS H_SCORE, TIME_BASED_DECISION, HYBRID_DECISION FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION <> HYBRID_DECISION
ORDER BY H_SCORE DESC
FETCH FIRST 10 ROWS ONLY;

CREATE OR REPLACE VIEW ARCHIVAL_STRATEGY_COMPARISON AS SELECT READING_ID, DATA_SIZE, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ACCESS_FREQUENCY, RECORD_STORAGE_UTILISATION, H_SCORE, CASE WHEN DAYS_SINCE_ACCESS >= 230 THEN 'ARCHIVE' ELSE 'KEEP' END AS TIME_BASED_DECISION, CASE WHEN H_SCORE >= 2.5 THEN 'ARCHIVE' ELSE 'KEEP' END AS HYBRID_DECISION FROM HYBRID_ARCHIVAL_NEW;
SELECT * FROM ARCHIVAL_STRATEGY_COMPARISON FETCH FIRST 10 ROWS ONLY;

SELECT ROUND(100 * (MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN ACTIVE_ARCHIVED END) - MAX(CASE WHEN STRATEGY = 'HYBRID' THEN ACTIVE_ARCHIVED END)) / MAX(CASE WHEN STRATEGY = 'TIME-BASED' THEN ACTIVE_ARCHIVED END), 4) AS ACTIVE_ARCHIVAL_REDUCTION_PERCENT FROM (
SELECT 'TIME-BASED' AS STRATEGY, SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS ACTIVE_ARCHIVED FROM ARCHIVAL_STRATEGY_COMPARISON WHERE TIME_BASED_DECISION = 'ARCHIVE'
UNION ALL
SELECT 'HYBRID', SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) FROM ARCHIVAL_STRATEGY_COMPARISON WHERE HYBRID_DECISION = 'ARCHIVE');
